<script setup lang="ts">
import { computed, ref } from 'vue';

const props = defineProps<{ state: any; participants: any[]; isPlayer: boolean; myPlayerId?: string; isDemo: boolean }>();
const emit = defineEmits<{ action: [action: any] }>();
const selectedTarget = ref<string>('');
const state = computed(() => props.state || {});
const me = computed(() => (state.value.players || []).find((player: any) => player.playerId === props.myPlayerId));
const availableActions = computed<string[]>(() => state.value.myAvailableActions || []);
const targets = computed(() => (state.value.players || []).filter((player: any) => player.alive && player.playerId !== props.myPlayerId && (availableActions.value.includes('WEREWOLF_KILL') ? player.roleId !== 'werewolf' : true)));
const nameOf = (id: string) => props.participants.find((p: any) => p.id === id)?.display_name || props.participants.find((p: any) => p.id === id)?.username || id.slice(0, 8);
const submit = (type: string) => { if (type.includes('VOTE') && !selectedTarget.value) return; emit('action', { type, ...(selectedTarget.value ? { targetPlayerId: selectedTarget.value } : {}) }); selectedTarget.value = ''; };
const phaseLabel: Record<string, string> = { NIGHT: 'Đêm', DAWN: 'Bình minh', DISCUSSION: 'Thảo luận', VOTING: 'Bỏ phiếu', EXECUTION: 'Xử quyết', LAST_WORD: 'Lời cuối', GAME_OVER: 'Kết thúc' };
</script>

<template>
  <section class="werewolf-arena">
    <div class="ww-header"><div><span class="ww-kicker">REAL-TIME SOCIAL DEDUCTION</span><h1>Ma Sói</h1></div><div class="ww-phase"><span>NGÀY {{ state.day || 0 }} · ĐÊM {{ state.night || 1 }}</span><strong>{{ phaseLabel[state.phase] || state.phase }}</strong></div></div>
    <div class="ww-grid">
      <main class="ww-table"><div class="ww-moon">☾</div><div class="ww-seats"><article v-for="player in state.players" :key="player.playerId" class="ww-seat" :class="{ dead: !player.alive, self: player.playerId === myPlayerId }"><span class="ww-avatar">{{ nameOf(player.playerId).slice(0, 1).toUpperCase() }}</span><strong>{{ nameOf(player.playerId) }}</strong><small>Ghế {{ player.seat }} · {{ player.alive ? 'Sống' : 'Đã chết' }}</small><em v-if="player.roleName">{{ player.roleName }}</em></article></div><div class="ww-events"><p v-for="event in (state.events || []).slice(-5).reverse()" :key="event.id"><span>•</span>{{ event.type.replaceAll('_', ' ') }}</p></div></main>
      <aside class="ww-sidebar"><div class="ww-role"><span class="ww-kicker">VAI TRÒ CỦA BẠN</span><h2>{{ me?.roleName || 'Bí mật' }}</h2><p>{{ me?.roleId === 'werewolf' ? 'Phối hợp với đồng đội trong đêm và chọn dân làng.' : 'Quan sát, suy luận và sống sót qua các cuộc bỏ phiếu.' }}</p><div v-if="me?.roleId === 'werewolf'" class="ww-pack">Đồng đội: {{ state.players.filter((p: any) => p.roleId === 'werewolf' && p.playerId !== myPlayerId).map((p: any) => nameOf(p.playerId)).join(', ') || 'Không có' }}</div></div>
        <div class="ww-action"><span class="ww-kicker">HÀNH ĐỘNG</span><p v-if="!isPlayer">Bạn đang xem với tư cách khán giả.</p><p v-else-if="!availableActions.length">Đang chờ hành động của người chơi khác.</p><template v-else><select v-model="selectedTarget"><option value="">Chọn người chơi</option><option v-for="target in targets" :key="target.playerId" :value="target.playerId">{{ nameOf(target.playerId) }} · ghế {{ target.seat }}</option></select><button v-if="availableActions.includes('WEREWOLF_KILL')" @click="submit('WEREWOLF_KILL')" :disabled="!selectedTarget">Săn đêm</button><button v-if="availableActions.includes('SEER_CHECK')" @click="submit('SEER_CHECK')" :disabled="!selectedTarget">Soi người này</button><button v-if="availableActions.includes('GUARD_PROTECT')" @click="submit('GUARD_PROTECT')" :disabled="!selectedTarget">Bảo vệ</button><button v-if="availableActions.includes('WITCH_HEAL')" @click="submit('WITCH_HEAL')">Dùng thuốc cứu</button><button v-if="availableActions.includes('WITCH_POISON')" @click="submit('WITCH_POISON')" :disabled="!selectedTarget">Dùng thuốc độc</button><button v-if="availableActions.includes('CAST_VOTE')" @click="submit('CAST_VOTE')" :disabled="!selectedTarget">Bỏ phiếu</button><button v-if="availableActions.includes('SKIP_VOTE')" class="muted" @click="submit('SKIP_VOTE')">Bỏ qua</button></template></div>
        <div class="ww-meta"><span>Trạng thái máy chủ</span><strong>Server authoritative</strong><span>Thông tin riêng tư</span><strong>Đã lọc theo vai trò</strong></div>
      </aside>
    </div>
  </section>
</template>

<style scoped>
