le h2{font-family:Georgia,serif;font-size:1.7rem;color:#f2d28f;margin:10px 0}.ww-role p,.ww-action p{color:#b6c0d0;font-size:.72rem;line-height:1.6}.ww-pack{padding:10px;border-radius:10px;background:#d7b77312;color:#e6cc93;font-size:.68rem}.ww-action{display:flex;flex-direction:column;gap:9px}.ww-action select,.ww-action button{border:1px solid #ffffff1c;border-radius:9px;padding:11px;background:#17233a;color:#f5f1e6;font-size:.7rem}.ww-action button{cursor:pointer;background:#b8863d;color:#111725;font-weight:800}.ww-action button:disabled{opacity:.45;cursor:not-allowed}.ww-action button.muted{background:transparent;color:#c4cad6}.ww-meta{display:grid;gap:5px;color:#8491a6;font-size:.64rem}.ww-meta strong{color:#83d0af;margin-bottom:10px}@media(max-width:850px){.ww-grid{grid-template-columns:1fr}.ww-seats{grid-template-columns:repeat(2,1fr)}.ww-table{min-height:720px}}@media(max-width:520px){.ww-header{align-items:start;flex-direction:column;gap:15px}.ww-phase{text-align:left}.ww-seats{grid-template-columns:1fr 1fr;gap:10px}.ww-table{padding:15px}.ww-events{left:15px;right:15px}}
</style>
